export const STRATEGY_BLOCKS: VerbatimBlock[] = [
  {body: 'Strategy'},
  {body: 'AIRD adopted a participatory and collaborative strategy for demonstrating Gram Swaraj in Village Garhi. The strategy recognizes that sustainable rural development can be achieved only when individuals, community institutions, government agencies, academic institutions, and development organizations work together towards a common goal.'},
  {heading: 'Building a foundation of values and service', body: 'AIRD seeks to bring together individuals and institutions willing to “Join Hands and Take Action” for establishing an appropriate community learning and development centre in Village Garhi. Inspired by the teachings of Swami Vivekananda and Gautama Buddha, the initiative promotes spiritual science, meditation, self-development, and service to humanity.'},
  {body: 'The organization encourages people to view service to the needy as a form of worship and to contribute their time, knowledge, and resources for the welfare of society. Students and young professionals are invited to participate as volunteers and gain practical experience in community development while contributing to the establishment of a live model of participatory governance.'},
  {heading: 'Promoting multi-stakeholder partnerships', body: 'The strategy aims to create a common platform where key stakeholders of rural development—including Self-Help Groups (SHGs), Gram Panchayats, Government Departments, Banks, NGOs, Corporate Institutions, Universities, and Research Organizations—can work together to achieve the shared objective of community empowerment and people’s governance.'},
  {body: 'Universities and research institutions are encouraged to demonstrate and validate their innovations, technologies, and development models in the village. Particular emphasis is placed on approaches that strengthen community participation, improve agricultural productivity, enhance livestock-based livelihoods, promote environmental conservation, and improve public health outcomes.'},
  {heading: 'Developing local Change Agents', body: 'Recognizing the importance of local leadership, AIRD seeks to identify and train rural youth as Change Agents (CAs). Practical training programmes are organized on participatory planning, implementation, monitoring, evaluation, and social accountability.'},
  {body: 'Self-Help Groups are encouraged to identify motivated young individuals who are willing to invest their time, energy, and commitment in community development. These youth are trained and mentored to facilitate development processes within their own villages, thereby ensuring local ownership and sustainability.'},
  {heading: 'Participatory planning and project development', body: 'AIRD supports community members in identifying local needs and opportunities through participatory discussions and collective decision-making. The organization facilitates the preparation of development projects and helps communities establish partnerships with government agencies, financial institutions, and corporate organizations for resource mobilization and implementation.'},
  {body: 'Special attention is given to strengthening community participation in flagship programmes such as:'},
  {body: 'MGNREGA'},
  {body: 'National Rural Livelihood Mission (NRLM)'},
  {body: 'Panchayati Raj initiatives'},
  {body: 'Rural livelihood and environmental programmes'},
  {body: 'Job card holders are encouraged to plan effectively for wage employment opportunities under MGNREGA and participate actively in social audits. Similarly, SHGs and their federations are supported in preparing Micro Investment Plans (MIPs) and Micro Credit Plans (MCPs) to strengthen household livelihoods and financial inclusion.'},
  {heading: 'Strengthening Gram Sabha and local governance', body: 'A central component of the strategy is strengthening the Gram Sabha as the foundation of democratic local governance. AIRD facilitates community participation in Gram Sabha meetings and supports the systematic documentation of discussions, resolutions, and development priorities.'},
  {body: 'The objective is to build the capacity of villagers to participate effectively in planning, monitoring, and evaluating local development interventions and to ensure transparency and accountability in the management of public resources.'},
  {heading: 'Community dialogue and Social Accountability', body: 'To encourage continuous dialogue among villagers, AIRD promotes the organization of Maitri Bhoj (Friendship Dinners) on every Full Moon (Purnima) and New Moon (Amavasya). These informal gatherings provide opportunities for community members to discuss issues related to service delivery, resource management, village development, and social harmony.'},
  {body: 'The organization also promotes electronic documentation of community feedback regarding the performance of local institutions such as Gram Panchayats, SHGs, government functionaries, and development programmes. These experiences are intended to be documented and shared through digital platforms to enhance transparency and public accountability.'},
  {heading: 'Village information and knowledge management', body: 'AIRD seeks to establish a Village Information Bank for systematically collecting, documenting, and monitoring information related to village resources, development initiatives, service delivery systems, and community priorities.'},
  {body: 'The information generated through participatory processes is intended to support evidence-based planning and decision-making. Village development plans and community initiatives are to be shared through digital platforms, inviting individuals and institutions to collaborate in achieving common development goals.'},
  {heading: 'Learning, reflection, and process improvement', body: 'At the completion of the demonstration phase, AIRD proposes to organize a workshop on participatory rural development to evaluate the effectiveness of the processes adopted. The workshop will review achievements, challenges, lessons learned, and innovations generated during implementation.'},
  {body: 'The ultimate objective is to refine and demonstrate a practical, replicable, and community-owned model of Gram Swaraj that strengthens local institutions, promotes transparency and accountability, enhances livelihoods, and empowers people to take collective responsibility for their own development.'},
  {body: 'Through this strategy, AIRD aims not merely to implement projects but to create a living demonstration of people-centred governance, participatory development, and sustainable rural transformation.'}
];

